window.RI2_UNITS = {"10":{"unit":10,"code":"RI2-U10","title":"FACING CHANGE","startNumber":240,"endNumber":256,"entries":[{"number":240,"term":"host","sourceTerm":"host (n,v)","spoken":"host","ipa":"host /hoʊst/","type":"verb · noun","meaning":"chủ nhà/người dẫn; đăng cai tổ chức","definition":"A person or place that receives guests or holds an event; to organize and provide the place for an event.","note":"","example":"The coastal city hopes to host an international conference on climate change."},{"number":241,"term":"melt","sourceTerm":"melt (v)","spoken":"melt","ipa":"melt /mɛlt/","type":"verb","meaning":"(băng) tan; làm tan","definition":"To change from a solid into a liquid, or to cause this change.","note":"","example":"As warmer air melts mountain ice, nearby communities face changes in their water supply."},{"number":242,"term":"exceed · excessive","sourceTerm":"exceed · excessive","spoken":"exceed , excessive","ipa":"exceed /ɪˈksiːd/ · excessive /ɪˈksɛsɪv/","type":"verb · adjective","meaning":"vượt quá giới hạn hoặc mức dự kiến · quá mức, nhiều hơn hợp lí","definition":"To be greater than a limit or expected amount; excessive means more than is reasonable or safe.","note":"exceed + giới hạn/số lượng, không cần than; excessive + danh từ mang sắc thái quá mức và thường tiêu cực.","example":"When temperatures exceed historical levels, excessive heat can damage roads and crops."},{"number":243,"term":"crack","sourceTerm":"crack (v,n)","spoken":"crack","ipa":"crack /kræk/","type":"verb · noun","meaning":"nứt; vết nứt","definition":"To develop a narrow break without separating completely; a crack is such a break.","note":"","example":"Repeated freezing and melting caused the rock to crack along an existing line."},{"number":244,"term":"slide into","sourceTerm":"slide (v) into","spoken":"slide into","ipa":"slide /slaɪd/ · into /ˈɪntu/","type":"verb","meaning":"trượt vào; dần rơi vào","definition":"To move smoothly downward or gradually enter an undesirable state.","note":"slide into có thể là trượt vào theo nghĩa đen hoặc dần rơi vào một tình trạng xấu.","example":"Without careful planning, a growing tourist town can slide into economic instability."},{"number":245,"term":"critical ~ very important","sourceTerm":"critical (a) ~ very important","spoken":"critical , very important","ipa":"critical /ˈkrɪtɪkəl/ · very /ˈvɛri/ · important /ˌɪˈmpɔːrtənt/","type":"adjective","meaning":"cực kỳ quan trọng; nghiêm trọng","definition":"Extremely important to an outcome, or very serious and dangerous.","note":"critical có thể là “cực kì quan trọng”, “nghiêm trọng/nguy kịch”, hoặc “có tính phân tích/phê bình”; chọn theo văn cảnh.","example":"Reliable data are critical to decisions about communities facing serious environmental change."},{"number":246,"term":"shift ~ change","sourceTerm":"shift (n) ~ change (n)","spoken":"shift , change","ipa":"shift /ʃɪft/ · change /tʃeɪndʒ/","type":"noun · noun","meaning":"sự chuyển dịch, sự thay đổi","definition":"A movement or change from one position, condition, or pattern to another.","note":"shift thường nhấn mạnh sự chuyển từ trạng thái/hướng/mô hình này sang trạng thái khác; change rộng hơn.","example":"The region has experienced a gradual shift from farming to tourism."},{"number":247,"term":"at stake ~ at risk","sourceTerm":"at stake ~ at risk","spoken":"at stake , at risk","ipa":"stake /steɪk/ · risk /rɪsk/","type":"word / phrase","meaning":"đang bị đe dọa, có nguy cơ mất","definition":"In danger of being lost, damaged, or negatively affected.","note":"at stake thường nói về thứ có thể mất trong một quyết định/cuộc cạnh tranh; at risk dùng rộng hơn cho người hoặc vật có nguy cơ bị hại.","example":"Thousands of jobs are at stake if the local water supply continues to decline."},{"number":248,"term":"appeal to ~ attract","sourceTerm":"appeal (v,n) to sb/st ~ attract (v) sb/st","spoken":"appeal to , attract","ipa":"appeal /əˈpiːl/ · attract /əˈtrækt/","type":"verb · verb · noun · phrase / pattern","meaning":"hấp dẫn ai; sự hấp dẫn","definition":"To interest or please someone; appeal is the quality that makes something attractive.","note":"appeal to sb: hấp dẫn ai; attract sb/st: thu hút người/vật. appeal còn có nghĩa kháng cáo hoặc kêu gọi tùy văn cảnh.","example":"The plan appeals to residents because lower costs give it broad public appeal."},{"number":249,"term":"stable · stability >< unstable · instability","sourceTerm":"stable · stability >< unstable · instability","spoken":"stable , stability , unstable , instability","ipa":"stable /ˈsteɪbəl/ · stability /stəˈbɪlɪti/ · unstable /əˈnsteɪbəl/ · instability /ˌɪnstəˈbɪlɪti/","type":"noun · adjective","meaning":"ổn định · sự ổn định · không ổn định · sự bất ổn","definition":"Stable means unlikely to change suddenly; stability is that condition, while unstable and instability express the opposite.","note":"","example":"A stable climate supports food production, whereas long periods of instability threaten harvests."},{"number":250,"term":"amenity ~ facility","sourceTerm":"amenity ~ facility","spoken":"amenity , facility","ipa":"amenity /əˈmɛnəti/ · facility /fəˈsɪlɪti/","type":"noun","meaning":"tiện ích giúp một nơi thuận tiện hoặc dễ chịu ~ cơ sở vật chất; trang thiết bị","definition":"A useful or pleasant facility provided for people in a place.","note":"amenity thường dùng số nhiều amenities cho tiện ích của khu dân cư, khách sạn hoặc địa điểm; facility là cơ sở/trang thiết bị cụ thể.","example":"The sports centre is a public facility, and its lockers and café are useful amenities."},{"number":251,"term":"economic # economical","sourceTerm":"economic # economical","spoken":"economic , economical","ipa":"economic /ˌɛkəˈnɑːmɪk/ · economical /ˌɛkəˈnɑːmɪkəl/","type":"adjective · adjective","meaning":"thuộc về kinh tế · tiết kiệm, ít lãng phí","definition":"Economic relates to the economy; economical means using money, time, or resources without waste.","note":"economic growth/policy/crisis: thuộc kinh tế; an economical car/method: tiết kiệm, ít lãng phí.","example":"The city needs an economical heating system that also supports long-term economic growth."},{"number":252,"term":"debate","sourceTerm":"debate (n,v)","spoken":"debate","ipa":"debate /dəˈbeɪt/","type":"verb · noun","meaning":"tranh luận; cuộc tranh luận","definition":"A formal or public discussion of opposing views; to discuss an issue in this way.","note":"debate an issue hoặc debate whether/how...; a debate about/on/over an issue.","example":"Scientists and local leaders continue to debate how quickly the town should adapt."},{"number":253,"term":"subsidy · subsidize","sourceTerm":"subsidy · subsidize","spoken":"subsidy , subsidize","ipa":"subsidy /ˈsʌbsɪdi/ · subsidize /ˈsʌbsɪˌdaɪz/","type":"noun · verb","meaning":"khoản trợ cấp · trợ cấp, hỗ trợ bằng tiền","definition":"A subsidy is money provided to support an activity; to subsidize is to provide this financial help.","note":"a subsidy for/to + lĩnh vực/tổ chức; subsidize là động từ “trợ cấp”.","example":"The government used a temporary subsidy to subsidize repairs to farms damaged by the flood."},{"number":254,"term":"sustainable","sourceTerm":"sustainable (a)","spoken":"sustainable","ipa":"sustainable /səˈsteɪnəbəl/","type":"adjective","meaning":"bền vững; thân thiện với môi trường","definition":"Able to continue over time without exhausting resources or causing serious environmental harm.","note":"sustainable không chỉ là “thân thiện môi trường”; từ này còn nhấn mạnh khả năng duy trì lâu dài.","example":"The island is developing sustainable tourism that protects water supplies and local culture."},{"number":255,"term":"anthropology · anthropologist","sourceTerm":"anthropology · anthropologist","spoken":"anthropology , anthropologist","ipa":"anthropology /ˌænθrəˈpɑːlədʒi/ · anthropologist /ˌænθrəˈpɑːlədʒəst/","type":"noun · noun","meaning":"nhân chủng học · nhà nhân chủng học","definition":"Anthropology is the study of human societies and cultures; an anthropologist conducts this study.","note":"","example":"The anthropologist studied how the community's traditions changed after families moved inland."},{"number":256,"term":"plant · power plant · manufacturing plant","sourceTerm":"plant · power plant · manufacturing plant","spoken":"plant , power plant , manufacturing plant","ipa":"plant /plænt/ · power /ˈpaʊɚ/ · manufacturing /ˌmænjəˈfæktʃɚɪŋ/","type":"noun","meaning":"nhà máy, cơ sở công nghiệp · nhà máy điện hoặc năng lượng · nhà máy sản xuất","definition":"A plant is a factory or industrial site; a power plant produces energy, while a manufacturing plant makes goods.","note":"plant trong bài này mang nghĩa nhà máy/cơ sở công nghiệp; đừng mặc định hiểu là “cây”.","example":"The old power plant will be replaced by a facility that produces energy from wind."}],"pronunciationFocus":[{"entryNumber":240,"points":[{"category":"final-sound","note":"host kết thúc bằng cụm /st/; không bỏ /t/"}]},{"entryNumber":242,"points":[{"category":"word-stress","note":"exceed và excessive đều nhấn âm tiết thứ hai"},{"category":"final-sound","note":"exceed kết thúc bằng /d/"}]},{"entryNumber":244,"points":[{"category":"linking","note":"Đọc liền slide‿into, nối /d/ cuối slide sang nguyên âm /ɪ/ của into"}]},{"entryNumber":249,"points":[{"category":"word-stress","note":"stable và unstable nhấn vào stable; stability và instability chuyển trọng âm sang âm tiết chứa /bɪl/"}]},{"entryNumber":251,"points":[{"category":"word-stress","note":"economic và economical đều nhấn vào âm tiết chứa /nɑːm/"}]},{"entryNumber":255,"points":[{"category":"word-stress","note":"anthropology và anthropologist đều nhấn vào âm tiết chứa /pɑːl/"}]},{"entryNumber":256,"points":[{"category":"word-stress","note":"manufacturing nhấn chính vào âm tiết chứa /fæk/"},{"category":"final-sound","note":"plant kết thúc bằng cụm /nt/"}]}]}};
